<?php require_once 'config.php';require_booking_access();$pageTitle='Agendar corrida';$errors=[];$selected=null;$qty=1;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$bid=(int)($_POST['bateria_id']??0);$qty=filter_var($_POST['quantidade']??0,FILTER_VALIDATE_INT);if(!$qty||$qty<1)$errors[]='A quantidade deve ser um número inteiro maior ou igual a 1.';try{if(!$errors){$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM baterias WHERE id=? FOR UPDATE');$s->execute([$bid]);$b=$s->fetch();if(!$b)throw new RuntimeException('Bateria não encontrada.');if(is_admin())throw new RuntimeException('Administradores não podem realizar reservas.');if(strtotime($b['data'].' '.$b['horario'])<=time())throw new RuntimeException('Essa bateria já ocorreu ou não aceita reservas.');if($b['status']!=='disponivel')throw new RuntimeException('Essa bateria não está disponível.');if($qty>$b['vagas_disponiveis'])throw new RuntimeException('Não há vagas suficientes para essa quantidade de participantes.');$userId=(int)user()['id'];$startAt = date('Y-m-d H:i:s', strtotime($b['data'].' '.$b['horario']));$s=$pdo->prepare('SELECT r.id FROM reservas r JOIN baterias b ON b.id=r.bateria_id WHERE r.usuario_id=? AND r.horario_inicio=? FOR UPDATE');$s->execute([$userId,$startAt]);if($s->fetch())throw new RuntimeException('Você já possui uma reserva para esse horário. Escolha outra bateria.');$total=(float)$b['preco']*$qty;$s=$pdo->prepare('INSERT INTO reservas(usuario_id,bateria_id,quantidade_participantes,valor_total,horario_inicio) VALUES(?,?,?,?,?)');$s->execute([$userId,$bid,$qty,$total,$startAt]);$s=$pdo->prepare('UPDATE baterias SET vagas_disponiveis=vagas_disponiveis-?, status=IF(vagas_disponiveis-?<=0,\'lotada\',status) WHERE id=?');$s->execute([$qty,$qty,$bid]);$pdo->commit();flash('Agendamento confirmado! Sua reserva foi registrada.');redirect('minhas-reservas.php');}}catch(Throwable $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$errors[]=$ex instanceof PDOException?'Não foi possível concluir a reserva. Tente novamente.':$ex->getMessage();}}
$baterias=db()->query("SELECT * FROM baterias WHERE TIMESTAMP(data,horario)>NOW() AND status IN ('disponivel','lotada') ORDER BY data,horario")->fetchAll();require 'includes/header.php'; ?>
<div class="page-top"><div><div class="eyebrow">Escolha sua próxima experiência</div><h1 class="page-title">Agendar corrida</h1></div><a class="btn dark" href="minhas-reservas.php">MINHAS RESERVAS</a></div><?php foreach($errors as $er): ?><div class="alert danger"><?= e($er) ?></div><?php endforeach; ?><div class="grid"><?php foreach($baterias as $b): ?><article class="card race-card"><div class="race-date"><?= date('d/m/Y',strtotime($b['data'])) ?> • <?= substr($b['horario'],0,5) ?></div><h3>BATERIA KART CENTER</h3><p class="muted" style="font-size:12px">Duração: <?= (int)$b['duracao'] ?> minutos</p><div class="race-meta"><span><?= (int)$b['vagas_disponiveis'] ?> vagas</span><strong class="price">R$ <?= number_format($b['preco'],2,',','.') ?></strong></div><?php if($b['vagas_disponiveis']>0&&$b['status']==='disponivel'): ?><form method="post" class="booking-form" data-price="<?= e($b['preco']) ?>" style="margin-top:17px"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="bateria_id" value="<?= (int)$b['id'] ?>"><div class="field"><label>Participantes</label><input type="number" name="quantidade" data-qty min="1" max="<?= (int)$b['vagas_disponiveis'] ?>" value="1" required></div><div class="row" style="align-items:center"><span class="muted" style="font-size:11px">Total estimado</span><strong data-total>R$ <?= number_format($b['preco'],2,',','.') ?></strong></div><button class="btn" style="width:100%;margin-top:12px">CONFIRMAR RESERVA</button></form><?php else: ?><span class="badge redbg">Bateria lotada</span><?php endif; ?></article><?php endforeach; ?></div><?php if(!$baterias): ?><div class="panel empty">Não há baterias futuras cadastradas no momento.</div><?php endif; ?><?php require 'includes/footer.php'; ?>
